public void updateShowAll(boolean _showAll)
{
    HcmPositionLookup locPositionLookup;
    Query             lookupQuery;

    if (_showAll)
    {
        // Show all positions: open + filled
        locPositionLookup = HcmPositionLookup::newAllPositions();
    }
    else
    {
        // Show only open positions
        locPositionLookup = HcmPositionLookup::newActivePositions();
        locPositionLookup.parmIncludeOpen(true);
        locPositionLookup.parmIncludeFilled(false);
    }

    lookupQuery = locPositionLookup.updateQuery();

    hcmPosition_ds.query(lookupQuery);
    hcmPosition_ds.executeQuery();
}

[FormControlEventHandler(formControlStr(HcmPositionLookup, NVShowAll), FormControlEventType::Modified)]
public static void NVShowAll_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormCheckBoxControl showAllControl = sender as FormCheckBoxControl;
    FormRun             formRun        = sender.formRun();

    formRun.updateShowAll(showAllControl.value());
}
